/**
 * @name Command injection via subprocess calls with untrusted input
 * @description Detects command injection vulnerabilities through subprocess calls with untrusted input
 * @kind problem
 * @problem.severity error
 * @id python/command-injection-subprocess
 * @tags security
 *       external/cwe/cwe-78
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource or
    exists(API::Node envAccess |
      envAccess = API::moduleImport("os").getMember("environ").getMember(_) and
      source = envAccess.getAValueReachableFromSource()
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(SystemCommandExecution cmd |
      sink = cmd.getCommand()
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;

from DataFlow::Node source, DataFlow::Node sink
where CommandInjectionFlow::flow(source, sink)
select sink, "Potential command injection from untrusted source $@.", source, "here"

/**
 * @name Open redirect from user input
 * @description User-controlled input flowing to redirect locations can enable phishing attacks
 * @kind problem
 * @problem.severity warning
 * @id python/open-redirect
 * @tags security
 *       external/cwe/cwe-601
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module OpenRedirectConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("os").getMember("environ").getMember("get").getACall() and
      source = call
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      // HTTP redirect calls
      call.getFunction().(DataFlow::AttrRead).getAttributeName() = "redirect" and
      sink = call.getArg(_)
    )
  }
}

module OpenRedirectFlow = TaintTracking::Global<OpenRedirectConfig>;

from DataFlow::Node source, DataFlow::Node sink
where OpenRedirectFlow::flow(source, sink)
select sink, "Potential open redirect from untrusted source $@.", source, "here"

/**
 * @name SQL injection
 * @description Detects SQL injection vulnerabilities
 * @kind problem
 * @problem.severity error
 * @id python/sql-injection
 * @tags security
 *       external/cwe/cwe-89
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module SqlInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(SqlExecution sql |
      sink = sql.getSql()
    )
  }
}

module SqlInjectionFlow = TaintTracking::Global<SqlInjectionConfig>;

from DataFlow::Node source, DataFlow::Node sink
where SqlInjectionFlow::flow(source, sink)
select sink, "Potential SQL injection from untrusted source $@.", source, "here"
